class Solution { public:vector<int> findThePrefixCommonArray(vector<int>& A,vector<int>& B){int n=A.size(),common=0;vector<bool> seenA(n+1),seenB(n+1);vector<int> answer(n);for(int i=0;i<n;++i){seenA[A[i]]=true;if(seenB[A[i]])++common;seenB[B[i]]=true;if(seenA[B[i]])++common;answer[i]=common;}return answer;} };
